// @productions equality if-else-stmt equality-expr boolean-literal assign-stmt local-var-decl-stmt int-literal
import ballerina/io;

public function main() {
    boolean b = true == true;
    if b {
        io:println(4); // @output 4
    }
    else {
        io:println(5); 
    }
    b = false == false;
    if b {
        io:println(6); // @output 6
    }
    else {
        io:println(7);
    }
    b = true != true;
    if b {
        io:println(8);  
    }
    else {
        io:println(9); // @output 9
    }
    b = true;
    if b == true {
        io:println(10); // @output 10
    }
    else {
        io:println(11);
    }
    b = false;
    if true == b {
        io:println(12); 
    }
    else {
        io:println(13); // @output 13
    }
}

